package mx.taller.vehicle;
import mx.taller.client.*; import mx.taller.workshop.*; import jakarta.validation.Valid; import org.springframework.beans.factory.annotation.Value; import org.springframework.core.io.*; import org.springframework.data.domain.*; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import java.nio.file.*; import java.util.*;
@RestController @RequestMapping("/api/vehiculos") public class VehiculoController {
 private final VehiculoRepository repo; private final ClienteRepository clientes; private final FotoRepository fotos; private final TallerRepository talleres; private final Path uploads; public VehiculoController(VehiculoRepository r,ClienteRepository c,FotoRepository f,TallerRepository t,@Value("${app.upload-dir:./uploads}") String dir){repo=r;clientes=c;fotos=f;talleres=t;uploads=Path.of(dir).toAbsolutePath().normalize();}
 @GetMapping @PreAuthorize("hasAnyRole('ADMINISTRADOR_TALLER','RECEPCIONISTA')") public Page<Vehiculo> listar(@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="10") int size,@RequestParam(defaultValue="marca") String sort,@RequestParam(defaultValue="asc") String dir){if(!Set.of("vin","placa","marca","modelo","anio","version","color").contains(sort))sort="marca";return repo.findByActivoTrue(PageRequest.of(Math.max(0,page),Math.min(10,Math.max(1,size)),Sort.by("desc".equalsIgnoreCase(dir)?Sort.Direction.DESC:Sort.Direction.ASC,sort)));}
 @GetMapping("/inactivos") @PreAuthorize("hasRole('ADMINISTRADOR_TALLER')") public Page<Vehiculo> inactivos(@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="10") int size,@RequestParam(defaultValue="marca") String sort,@RequestParam(defaultValue="asc") String dir){if(!Set.of("vin","placa","marca","modelo","anio","version","color").contains(sort))sort="marca";return repo.findByActivoFalse(PageRequest.of(Math.max(0,page),Math.min(10,Math.max(1,size)),Sort.by("desc".equalsIgnoreCase(dir)?Sort.Direction.DESC:Sort.Direction.ASC,sort)));}
 @PostMapping(consumes="multipart/form-data") @PreAuthorize("hasAnyRole('ADMINISTRADOR_TALLER','RECEPCIONISTA')") public Vehiculo crear(@Valid @ModelAttribute VehiculoDto d,@RequestPart(required=false) List<MultipartFile> imagenes)throws Exception {if(!talleres.existsByActivoTrue())throw new IllegalArgumentException("Primero debe configurarse el taller");String vin=d.vin().replaceAll("\\s","").toUpperCase(),placa=d.placa().replaceAll("\\s","").toUpperCase();if(repo.existsByVinIgnoreCaseOrPlacaIgnoreCase(vin,placa))throw new IllegalArgumentException("VIN o placa duplicados");Cliente c=clientes.findByIdAndActivoTrue(UUID.fromString(d.clienteId())).orElseThrow(()->new IllegalArgumentException("El cliente debe estar activo"));Vehiculo v=repo.save(new Vehiculo(c,vin,placa,d.marca(),d.modelo(),Short.parseShort(d.anio()),d.version(),d.color()));if(imagenes!=null)for(MultipartFile f:imagenes){if(f.isEmpty())continue;TallerController.validarFoto(f);Path dir=uploads.resolve("vehiculos");Files.createDirectories(dir);String type=f.getContentType(),name=UUID.randomUUID()+("image/png".equals(type)?".png":".jpg");Path out=dir.resolve(name).normalize();if(!out.startsWith(dir))throw new IllegalArgumentException("Ruta inválida");f.transferTo(out);fotos.save(new FotoVehiculo(v,out.toString(),type));}return v;}
 @GetMapping("/{id}/fotos") @PreAuthorize("hasAnyRole('ADMINISTRADOR_TALLER','RECEPCIONISTA')") public List<Map<String,Object>> fotos(@PathVariable UUID id){return fotos.findByVehiculoIdAndActivoTrue(id).stream().map(f->Map.<String,Object>of("id",f.getId(),"tipo",f.getTipo(),"url","/vehiculos/fotos/"+f.getId()+"/contenido")).toList();}
 @GetMapping("/fotos/{fotoId}/contenido") @PreAuthorize("hasAnyRole('ADMINISTRADOR_TALLER','RECEPCIONISTA')") public ResponseEntity<Resource> contenido(@PathVariable UUID fotoId){FotoVehiculo f=fotos.findById(fotoId).filter(FotoVehiculo::isActivo).orElseThrow(()->new IllegalArgumentException("Foto no encontrada"));try{Path p=Path.of(f.getRuta()).toAbsolutePath().normalize();if(!p.startsWith(uploads)||!Files.isRegularFile(p))throw new IllegalArgumentException("Foto no disponible");return ResponseEntity.ok().contentType(MediaType.parseMediaType(f.getTipo())).header(HttpHeaders.CACHE_CONTROL,"private, max-age=3600").body(new FileSystemResource(p));}catch(InvalidPathException e){throw new IllegalArgumentException("Ruta de foto inválida");}}
 @DeleteMapping("/{id}") @PreAuthorize("hasRole('ADMINISTRADOR_TALLER')") public Map<String,String> desactivar(@PathVariable UUID id){Vehiculo v=repo.findById(id).filter(Vehiculo::isActivo).orElseThrow(()->new IllegalArgumentException("Vehículo no encontrado"));v.setActivo(false);repo.save(v);fotos.findByVehiculoId(id).forEach(f->{f.setActivo(false);fotos.save(f);});return Map.of("mensaje","Vehículo y fotos desactivados");}
 @PatchMapping("/{id}/reactivar") @PreAuthorize("hasRole('ADMINISTRADOR_TALLER')") @jakarta.transaction.Transactional public Map<String,String> reactivar(@PathVariable UUID id){Vehiculo v=repo.findByIdAndActivoFalse(id).orElseThrow(()->new IllegalArgumentException("Vehículo inactivo no encontrado"));if(!v.getCliente().isActivo())throw new IllegalArgumentException("Primero reactive el cliente asociado");v.setActivo(true);repo.save(v);fotos.findByVehiculoId(id).forEach(f->{f.setActivo(true);fotos.save(f);});return Map.of("mensaje","Vehículo y fotos reactivados");}
}
